ikasi & Praktik Baik","summary":"Dokumentasi kegiatan, laporan, publikasi, portofolio, dan penyebarluasan praktik baik.","body":"Dokumentasi kegiatan, laporan, publikasi, portofolio, dan penyebarluasan praktik baik.","details":{"source_ref":"tp2026-2027-team-6","record_type":"team","team":"Dokumentasi, Publikasi & Praktik Baik","position":"Tupoksi Tim","term":"2026/2027","target":"Portofolio digital KKG, dokumentasi kegiatan, dan kumpulan praktik baik."},"status":"published","sort_order":106}]}$kkg_source$::jsonb;
  item jsonb;
  matched uuid;
  existing_count integer;
  attendance_before bigint;
BEGIN
  SELECT count(*) INTO attendance_before FROM public.attendance;
  IF jsonb_array_length(source->'schedules') <> 11 OR jsonb_array_length(source->'teachers') <> 22 OR jsonb_array_length(source->'content') <> 40 THEN
    RAISE EXCEPTION 'Source counts do not match reviewed data';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(source->'teachers') LOOP
    IF EXISTS (SELECT 1 FROM public.teachers WHERE upper(name)=upper(item->>'name') AND id<>item->>'id') THEN
      RAISE EXCEPTION 'Teacher name already exists with another ID: %', item->>'name';
    END IF;
    INSERT INTO public.teachers(id,name,school,role) VALUES(item->>'id',item->>'name',item->>'school',item->>'role')
    ON CONFLICT(id) DO UPDATE SET name=excluded.name,school=excluded.school,role=excluded.role,updated_at=now();
  END LOOP;

  FOR item IN SELECT value FROM jsonb_array_elements(source->'schedules') LOOP
    INSERT INTO public.schedules(id,title,date,time,location,agenda,status)
    VALUES(item->>'id',item->>'title',(item->>'date')::date,item->>'time',item->>'location',item->'agenda',item->>'status')
    ON CONFLICT(id) DO UPDATE SET title=excluded.title,date=excluded.date,time=excluded.time,location=excluded.location,agenda=excluded.agenda,status=excluded.status,updated_at=now();
  END LOOP;

  FOR item IN SELECT value FROM jsonb_array_elements(source->'content') LOOP
    SELECT count(*),min(id::text)::uuid INTO existing_count,matched
    FROM public.kkg_content
    WHERE details->>'source_ref'=item->'details'->>'source_ref'
       OR (item ? 'existing_id' AND id=(item->>'existing_id')::uuid);
    IF existing_count > 1 THEN RAISE EXCEPTION 'Duplicate source reference: %',item->'details'->>'source_ref'; END IF;
    IF matched IS NOT NULL THEN
      UPDATE public.kkg_content SET title=item->>'title',summary=item->>'summary',body=item->>'body',
        details=details || (item->'details'),status=item->>'status',sort_order=(item->>'sort_order')::integer
      WHERE id=matched AND kind=item->>'kind';
      IF NOT FOUND THEN RAISE EXCEPTION 'Content kind mismatch'; END IF;
    ELSE
      INSERT INTO public.kkg_content(kind,title,summary,body,details,status,sort_order)
      VALUES(item->>'kind',item->>'title',item->>'summary',item->>'body',item->'details',item->>'status',(item->>'sort_order')::integer);
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.attendance) <> attendance_before THEN RAISE EXCEPTION 'Unexpected attendance change'; END IF;
END
$kkg_import$;
COMMIT;
